/* ---------- Hand-off to a person ---------- */
/* the agent passes a conversation to a person: why, who has it (with Reassign), when the reply is due, what they need to
   pick it up, and what the customer was told, with a status line at the foot. The type and spacing are Draft review's; the
   two columns stack when narrow. Its content is 16px from every edge */
.hox{position:relative;width:100%;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.hox-h{display:flex;align-items:center;gap:var(--dm-s-3)}
.hox-ic{width:32px;height:32px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-chip);color:var(--dm-fg2);display:grid;place-items:center;flex:none}
.hox-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.hox-ht b{font-weight:500;font-size:14px;line-height:20px}
.hox-ht span{font-size:13px;line-height:18px}
.hox-b{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:var(--dm-s-4) var(--dm-s-6);align-items:start;padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
@container (max-width:600px){.hox-b{grid-template-columns:minmax(0,1fr)}.hox-col+.hox-col{padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}}
.hox-col{display:flex;flex-direction:column;gap:var(--dm-s-2);min-width:0}
.hox-lb{font-size:12px;color:var(--dm-muted)}
.hox-who{display:flex;align-items:center;gap:var(--dm-s-3);min-height:40px}
.hox-av{width:32px;height:32px;display:grid;place-items:center;flex:none;border-radius:50%;background:var(--dm-chip);color:var(--dm-fg2)}
/* the person's avatar is as big as the head's tile, so its words start where the title's do */
.hox-av .av{width:32px;height:32px;font-size:12px}
.hox-wt{flex:1;min-width:0;display:flex;flex-direction:column}
.hox-wt b{font-weight:500;font-size:13.5px;line-height:20px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.hox-wd{display:flex;align-items:center;gap:6px;font-size:12px;line-height:18px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.hox-wd .dot{color:var(--dm-faint)}
/* the person's status: the dot is a mark (--dm-ok-mark, --dm-warn-mark) and the words keep the text colours */
.hox-wd.ok .dot{color:var(--dm-ok-mark)}
.hox-wd.warn{color:var(--dm-warn)}
.hox-wd.warn .dot{color:var(--dm-warn-mark)}
/* Reassign: a small dropdown, like the one for how long in Permission gate. It is the row's last control, so its words end on
   the content's right edge (where the target time under it ends) and its hover box reaches 8px out round them */
.hox-rb{display:inline-flex;align-items:center;gap:6px;height:28px;margin-right:calc(-1 * var(--dm-s-2));padding:0 var(--dm-s-2);border-radius:var(--dm-r-pill);font-size:13px;color:var(--dm-fg2);flex:none;transition:background .16s,color .16s}
.hox-rb[aria-expanded="true"]{background:var(--dm-row);color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.hox-rb:hover{background:var(--dm-row);color:var(--dm-fg)}}
.hox-rb>svg{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.hox-rb[aria-expanded="true"]>svg{transform:rotate(180deg)}
.hox-rb[disabled]{opacity:1;cursor:not-allowed;background:none;color:var(--dm-dis)}
.hox-rb[disabled]>svg{color:var(--dm-dis)}
.hox-pop{min-width:240px}
/* its menu opens out of the card, which keeps its height while the menu is open */
.hox.growing:has(.hox-pop.open){overflow:visible}
.hox-pop .mi .av{width:20px;height:20px;font-size:9px}
.hox-pop .mi>span:not(.ck):not(.av){flex:1;min-width:0}
/* when the reply is due: the line counts down and the bar empties, amber in the last five minutes. The due time and the target
   are two sizes on one line, so they share a baseline in their own wrapper; the clock sits on the line's centre */
.hox-sla{display:flex;flex-direction:column;gap:var(--dm-s-2);padding-top:var(--dm-s-2)}
.hox-sl{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13px}
.hox-sl>svg{color:var(--dm-fg2);flex:none}
.hox-sw{flex:1;min-width:0;display:flex;align-items:baseline;gap:var(--dm-s-2)}
.hox-sw .muted{margin-left:auto;font-size:12px;white-space:nowrap}
.hox-due{min-width:0}
.hox-bar{height:4px;border-radius:2px;background:var(--dm-chip);overflow:hidden}
.hox-bar i{display:block;height:100%;width:100%;border-radius:inherit;background:var(--dm-fg2);transition:width 1s linear,background .3s}
.hox-sla.warn .hox-sl>svg,.hox-sla.warn .hox-due{color:var(--dm-warn)}
.hox-sla.warn .hox-bar i{background:var(--dm-warn-mark)}
.hox-sla.bad .hox-sl>svg,.hox-sla.bad .hox-due{color:var(--dm-bad)}
.hox-sla.bad .hox-bar i{background:var(--dm-bad-mark)}
.hox-sum{margin:0;font-size:13px;line-height:1.5;color:var(--dm-fg2)}
.hox-facts{display:flex;flex-direction:column;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.hox-f{display:flex;align-items:center;gap:var(--dm-s-3);min-height:32px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13px}
.hox-f .k{width:72px;flex:none;color:var(--dm-muted)}
.hox-f .v{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.hox-lnk{align-self:flex-start;max-width:100%}
.hox-lnk>span{overflow:hidden;text-overflow:ellipsis}
/* what the customer was told, editable in place. Edit is a ghost button, the row's last control, so its words end on the
   content's right edge (where the message box ends) */
.hox-ms{display:flex;flex-direction:column;gap:var(--dm-s-2);margin-top:var(--dm-s-1);padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.hox-mh{display:flex;align-items:center;gap:var(--dm-s-2);min-height:28px}
.hox-mh .sp{flex:1}
.hox-mh .pill.ghost:last-child{margin-right:-11px}
.hox-mb{padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13.5px;line-height:1.5;outline:0;transition:box-shadow var(--dm-t-fast),background var(--dm-t-fast)}
.hox-mb[contenteditable="true"]{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent)}
@supports (corner-shape:squircle){.hox-mb[contenteditable="true"]{corner-shape:squircle;border-radius:var(--dm-r-box-sq)}}
.hox-mb[contenteditable="true"]:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
/* where it stands: the card's footer, under a hairline, 16px from it and from the card's bottom edge. Its mark sits centred in
   the head's 32px tile column and its words start where the title's do. It is neutral while it waits (a spinner, the words
   with the loader's sweep), a warning notice when the person can't take it (owner, 18 Nov: a faint warning tint reaching 8px
   out round the row, the filled warning sign in --dm-warn-mark, the words in the text colours and Reassign, the action that
   settles it, as .pill.warn), and a neutral row with the person's avatar once they have it: no green fill (owner, 18 Nov) */
.hox-st{margin-top:var(--dm-s-1);padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.hox-sr{display:grid;grid-template-columns:32px minmax(0,1fr) auto;align-items:center;column-gap:var(--dm-s-3);min-height:28px;margin:calc(-1 * var(--dm-s-2));padding:var(--dm-s-2);border-radius:calc(var(--dm-r-card) - 8px);transition:background-color .32s var(--dm-ease)}
.hox-st.warn .hox-sr{background:color-mix(in srgb,var(--dm-warn-bg) 45%,transparent)}
.hox-sr .g{width:32px;height:20px;display:grid;place-items:center;color:var(--dm-fg2)}
.hox-sr .g .av{width:20px;height:20px;font-size:8.5px}
.hox-st.ok .g{color:var(--dm-ok)}
:root[data-style="clean"] .hox-st.ok .g,:root [data-style="clean"] .hox-st.ok .g,:root [data-style="clean"].hox-st.ok .g{color:var(--dm-ok-mark)}
.hox-wi{width:16px;height:16px;overflow:visible}
.hox-wi .a{fill:var(--dm-warn-mark);stroke:var(--dm-warn-mark);stroke-width:2;stroke-linejoin:round}
.hox-wi .b{fill:none;stroke:var(--dm-surface);stroke-width:2.2;stroke-linecap:round}
.hox-sr .t{min-width:0;display:flex;flex-direction:column;font-size:13px;line-height:20px;color:var(--dm-fg)}
.hox-sr .t b{font-weight:500}
.hox-sr .t>span{font-size:12.5px;line-height:18px;color:var(--dm-muted)}
.hox-st.warn .hox-sr .t>span{color:var(--dm-fg2)}
.hox-sr .t,.hox-sum,.hox-mb,.tmx-note>span{text-wrap:pretty}
/* on a phone the notice's Reassign goes under its words, starting where they start, so the words keep the row's width; the
   mark stays on the title's line */
@container (max-width:480px){.hox-sr{grid-template-columns:32px minmax(0,1fr);align-items:start}.hox-sr .pill{grid-column:2;justify-self:start;margin-top:var(--dm-s-2)}}
/* Clean (owner, 17 and 18 Nov): the head's tile with a hairline, the footer an off-white foot strip whose words and Reassign
   sit 16px from its hairline and the card's bottom edge (--dm-strip-y) and 16px in from the sides; when the person can't take it
   the strip itself takes the faint warning tint. Reassign at the top is Clean's quiet select: the one hover, and the stronger
   fill while its menu is open */
:root[data-style="clean"] .hox.panel,:root [data-style="clean"] .hox.panel,:root [data-style="clean"].hox.panel{padding:16px 16px 0}
:root[data-style="clean"] .hox-ic,:root [data-style="clean"] .hox-ic,:root [data-style="clean"].hox-ic{box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .hox-ht b,:root [data-style="clean"] .hox-ht b,:root [data-style="clean"].hox-ht b{letter-spacing:-.01em}
:root[data-style="clean"] .hox-rb,:root [data-style="clean"] .hox-rb,:root [data-style="clean"].hox-rb{color:var(--dm-fg2);transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .hox-rb:not([disabled]):hover,:root [data-style="clean"] .hox-rb:not([disabled]):hover,:root [data-style="clean"].hox-rb:not([disabled]):hover{background:var(--dm-row);color:var(--dm-fg)}}
:root[data-style="clean"] .hox-rb[aria-expanded="true"],:root [data-style="clean"] .hox-rb[aria-expanded="true"],:root [data-style="clean"].hox-rb[aria-expanded="true"]{background:var(--dm-row-on);color:var(--dm-fg)}
:root[data-style="clean"] .hox-bar,:root [data-style="clean"] .hox-bar,:root [data-style="clean"].hox-bar{box-shadow:var(--dm-track-ring)}
:root[data-style="clean"] .hox-st,:root [data-style="clean"] .hox-st,:root [data-style="clean"].hox-st{margin:var(--dm-s-1) -16px 0;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card);transition:background-color .32s var(--dm-ease)}
:root[data-style="clean"] .hox-st.warn,:root [data-style="clean"] .hox-st.warn,:root [data-style="clean"].hox-st.warn{background:color-mix(in srgb,var(--dm-warn-bg) 45%,var(--dm-surface))}
:root[data-style="clean"] .hox-st .hox-sr,:root [data-style="clean"] .hox-st .hox-sr,:root [data-style="clean"].hox-st .hox-sr{margin:0;padding:0;background:none}

DM.def('human-handoff', (r, c) => {
  const IC = { user:I('user'), chev:I('chev-d','xs'), clock:I('clock'), link:I('link','xs'), edit:I('edit','xs') };
  r.innerHTML = r.innerHTML.replace(/\{(\w+)\}/g, (m, k) => IC[k] || m);
  const root = $('.hox', r), rb = $('.hox-rb', r), av = $('.hox-av', r), wn = $('.hox-wn', r), wd = $('.hox-wd', r), pop = $('.hox-pop', r);
  const sla = $('.hox-sla', r), due = $('.hox-due', r), bar = $('.hox-bar', r), fill = $('.hox-bar i', r);
  const row = $('.hox-st', r), sa = $('.hox-sa', r), sb = $('.hox-sb', r), mb = $('.hox-mb', r), ed = $('.hox-ed', r), no = $('.hox-no', r), ml = $('.hox-ml', r);
  // the card grows and shrinks with what it holds (a status that takes another line, the notice's button), centred in its stage
  c.offs.push(grow(root));
  // the billing team: someone free takes the conversation in a few seconds, someone in a call takes longer, and someone
  // who is out never does
  const P = [
    { k:'alex', n:'Alex Rivera', i:'AR', bg:'var(--dm-av-m)', on:'Available', tone:'ok', wait:2500 },
    { k:'sam', n:'Sam Ortiz', i:'SO', bg:'var(--dm-av-p)', on:'In a call', tone:'', wait:6000 },
    { k:'maya', n:'Maya Chen', i:'MC', bg:'var(--dm-av-l)', on:'Out until 2pm', tone:'warn' }
  ];
  const first = p => p.n.split(' ')[0];
  pop.insertAdjacentHTML('beforeend', P.map(p => `<button class="mi" role="menuitemradio" aria-checked="false" data-close data-k="${p.k}">${AV(p.i, p.bg)}<span>${p.n}<span class="d">Billing · ${p.on}</span></span><span class="ck">${I('check','xs')}</span></button>`).join(''));
  // when the reply is due: 15 minutes from the hand-off, counting down by the second; amber under five minutes
  const TARGET = 900;
  let left = 846;
  const showDue = () => {
    const m = Math.floor(left / 60);
    due.textContent = left <= 0 ? 'Reply overdue' : m < 1 ? 'Reply due in under a minute' : `Reply due in ${m} min`;
    sla.classList.toggle('warn', left > 0 && left < 300); sla.classList.toggle('bad', left <= 0);
    fill.style.width = Math.max(0, left / TARGET * 100) + '%'; bar.setAttribute('aria-valuenow', Math.max(0, left));
  };
  showDue(); c.every(1000, () => { left--; showDue(); });
  // the row at the foot says where it stands
  // the footer says where it stands: waiting (a spinner, the words with the loader's sweep), a warning notice with Reassign when
  // the person can't take it, or the person who has it
  const go = $('.hox-go', r), WARN = '<svg class="hox-wi" viewBox="0 0 24 24" aria-hidden="true"><path class="a" d="M12 3.6 2.6 19.9h18.8z"/><path class="b" d="M12 9.6v4.4M12 17v.01"/></svg>';
  const state = (tone, glyph, a, b) => {
    row.className = 'hox-st' + (tone ? ' ' + tone : ''); $('.g', row).innerHTML = glyph; sa.classList.toggle('shim', !tone); swap(sa, a); swap(sb, b);
    const ask = tone === 'warn'; if (go.hidden === ask){ go.hidden = !ask; if (ask) enter(go); }
  };
  let who = null, run = 0, phase = 'finding';
  function assign(p){
    const id = ++run; who = p; phase = 'waiting';
    av.innerHTML = AV(p.i, p.bg); enter(av.firstElementChild);
    swap(wn, p.n); wd.className = 'hox-wd'; wd.innerHTML = '<span>Billing</span>';
    $$('.mi', pop).forEach(m => m.setAttribute('aria-checked', m.dataset.k === p.k)); rb.disabled = false;
    state('', '<span class="spin"></span>', `Waiting for ${first(p)} to accept`, 'The agent has stopped replying to Dana');
    // their status comes back a moment later
    c.later(1600, () => {
      if (id !== run) return;
      wd.className = 'hox-wd' + (p.tone ? ' ' + p.tone : ''); wd.innerHTML = `<span class="dot"></span><span>Billing · ${p.on}</span>`; enter(wd);
      if (!p.wait){ phase = 'away'; state('warn', WARN, `${first(p)} is out until 2pm`, 'The reply is due before then. Reassign it to someone who is free.'); return; }
      c.later(p.wait, () => {
        if (id !== run) return;
        phase = 'joined'; state('ok', AV(p.i, p.bg), `${first(p)} joined`, 'Reading the conversation');
        c.later(1800, () => { if (id !== run) return; phase = 'with'; state('ok', AV(p.i, p.bg), `With ${first(p)} · agent paused`, `The agent won't reply while ${first(p)} has it`); });
      });
    });
  }
  $$('.mi', pop).forEach(m => m.addEventListener('click', () => { const p = P.find(x => x.k === m.dataset.k); if (p !== who) assign(p); }));
  // the preview hands it to Maya once on its own, unless you have picked someone first
  c.auto(1500, () => assign(P[2]));
  // what the customer was told can be corrected in place
  let said = mb.textContent, editing = false;
  const edit = on => {
    editing = on; mb.contentEditable = on ? 'true' : 'false'; mb.setAttribute('aria-readonly', !on); no.hidden = !on;
    ed.className = 'pill sm hox-ed ' + (on ? 'primary' : 'ghost'); ed.innerHTML = on ? 'Save' : I('edit','xs') + 'Edit';
    if (on){ mb.focus(); const s = getSelection(); s.selectAllChildren(mb); s.collapseToEnd(); }
  };
  ed.onclick = () => {
    if (!editing) return edit(true);
    const t = mb.textContent.trim();
    if (t && t !== said){ said = t; swap(ml, 'Sent to Dana · edited'); } else mb.textContent = said;
    edit(false);
  };
  no.onclick = () => { mb.textContent = said; edit(false); };
  // the preview's story: Maya is assigned but is out, so the person reassigns it to Alex, who takes it
  c.story(async s => {
    await s.until(() => phase === 'away'); await s.beat(4);
    await s.tap(go); await s.beat(2);
    await s.point($('.mi[data-k="sam"]', pop), false); await s.beat(1);
    await s.tap($('.mi[data-k="alex"]', pop)); s.away();
    await s.until(() => phase === 'with'); await s.beat(6);
  });
});
